package com.bank.balance;

import java.math.BigDecimal;

// A BST node keyed by account balance.
public class BalanceNode {
    private final BigDecimal balance;
    private BalanceNode left;
    private BalanceNode right;

    public BalanceNode(BigDecimal balance) {
        this.balance = balance;
    }

    public BigDecimal getBalance() { return balance; }
    public BalanceNode getLeft() { return left; }
    public BalanceNode getRight() { return right; }
    public void setLeft(BalanceNode left) { this.left = left; }
    public void setRight(BalanceNode right) { this.right = right; }
}
