package com.bank.balance;

import java.math.BigDecimal;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.logging.Logger;

// Finds the kth smallest balance via inorder traversal with early stop.
public class KthSmallestService {

    private static final Logger log = Logger.getLogger(KthSmallestService.class.getName());

    public BigDecimal kthSmallest(BalanceNode root, int k) {
        if (k <= 0) {
            throw new IllegalArgumentException("k must be positive");
        }
        Deque<BalanceNode> stack = new ArrayDeque<>();
        BalanceNode curr = root;
        int remaining = k;

        while (curr != null || !stack.isEmpty()) {
            // Descend to the smallest unvisited node.
            while (curr != null) {
                stack.push(curr);
                curr = curr.getLeft();
            }
            // Visit it in ascending order.
            curr = stack.pop();
            if (--remaining == 0) {
                return curr.getBalance(); // kth smallest reached, stop early
            }
            curr = curr.getRight();
        }
        throw new IllegalArgumentException("k exceeds number of nodes");
    }

    public BigDecimal findKthLowest(BalanceNode root, int k) {
        BigDecimal result = kthSmallest(root, k);
        log.info(() -> k + "th smallest balance = " + result);
        return result;
    }
}
