package com.bank.balance;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class KthSmallestDemo {

    private static final Logger log = Logger.getLogger(KthSmallestDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BalanceNode node(String amount) {
        return new BalanceNode(new BigDecimal(amount));
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Kth Smallest Balance");

        // BST of balances:    5000
        //                    /     \
        //                 3000     8000
        //                /   \        \
        //             1000  4000     9000
        BalanceNode root = node("5000");
        root.setLeft(node("3000"));
        root.setRight(node("8000"));
        root.getLeft().setLeft(node("1000"));
        root.getLeft().setRight(node("4000"));
        root.getRight().setRight(node("9000"));

        KthSmallestService service = new KthSmallestService();
        service.findKthLowest(root, 1); // 1000
        service.findKthLowest(root, 3); // 4000
        service.findKthLowest(root, 6); // 9000
    }
}
